from typing import Callable, Sequence

def lawvere_fixed_point(
    domain: Sequence[int],
    e: Callable[[int], Callable[[int], str]],
    f: Callable[[str], str],
) -> str:
    """Constructive Lawvere: from a point-surjective coding e and endomap f,
    build the diagonal g(x) = f(e_x(x)), find its code a, return e_a(a)."""
    def g(x: int) -> str:
        return f(e(x)(x))
    for a in domain:
        if all(e(a)(x) == g(x) for x in domain):
            c = e(a)(a)
            assert f(c) == c
            return c
    raise ValueError("coding was not point-surjective")

if __name__ == "__main__":
    domain = [0]
    e = lambda a: (lambda x: "*")
    f = lambda c: c
    print("fixed point:", lawvere_fixed_point(domain, e, f))

from typing import Callable

def bit_size(y: int) -> int:
    return y.bit_length()

def berry_incompressible(enc: Callable[[int], int], n: int) -> int:
    """Return x in {0..2**n} with complexity bit_size(enc(x)) > n (pigeonhole)."""
    for x in range(2 ** n + 1):
        if bit_size(enc(x)) > n:
            return x
    raise AssertionError("enc not injective")

if __name__ == "__main__":
    enc = lambda x: x
    for n in range(1, 8):
        x = berry_incompressible(enc, n)
        print(f"n={n}: K({x}) = {bit_size(enc(x))} > {n}")

from typing import Dict

NEG = {"T": "F", "F": "T", "B": "B", "N": "N"}
DES = {"T": True, "F": False, "B": True, "N": False}
TRUTH: Dict[int, str] = {0: "B", 1: "B", 2: "B", 3: "T", 4: "F", 5: "N"}
PARADOX = {0: "Liar", 1: "Russell", 2: "Berry"}

def provable(s: int) -> bool:
    return DES[TRUTH[s]]

def inconsistency_degree() -> int:
    return sum(1 for v in TRUTH.values() if v == "B")

def has_explosion() -> bool:
    if any(v == "B" for v in TRUTH.values()):
        return all(DES[v] for v in TRUTH.values())
    return False

if __name__ == "__main__":
    print("paradoxes provable & glut:",
          all(provable(s) and TRUTH[s] == "B" for s in PARADOX))
    print("self-sound:", all(DES[TRUTH[s]] for s in TRUTH if provable(s)))
    print("non-explosive:", not has_explosion())
    print("inconsistency degree:", inconsistency_degree())

