function CERTIFY(truth, paradox_tokens):
    DES = {T:true, B:true, F:false, N:false}
    provable(s) = DES[truth[s]]
    a <- for all t in paradox_tokens: provable(t) and truth[t] == B
    b <- for all s: (provable(s) implies DES[truth[s]])
    explode <- (exists s: truth[s]==B) and (for all s: DES[truth[s]])
    c <- not explode
    d <- count(s : truth[s] == B)
