"""Belnap truth-value lattice and negation action (matplotlib)."""
import matplotlib.pyplot as plt

def plot_belnap() -> None:
    pos = {"N": (0, 0), "F": (-1, 1), "T": (1, 1), "B": (0, 2)}
    neg = {"T": "F", "F": "T", "B": "B", "N": "N"}
    designated = {"T": True, "F": False, "B": True, "N": False}
    fig, ax = plt.subplots(figsize=(6, 6))
    edges = [("N", "F"), ("N", "T"), ("F", "B"), ("T", "B")]
    for a, b in edges:
        (x1, y1), (x2, y2) = pos[a], pos[b]
        ax.plot([x1, x2], [y1, y2], color="gray", zorder=1)
    for v, (x, y) in pos.items():
        color = "#2ca02c" if designated[v] else "#d62728"
        ax.scatter([x], [y], s=1600, color=color, zorder=2, edgecolors="black")
        ax.text(x, y, v, ha="center", va="center", fontsize=18, color="white")
    # negation as arrows (self-loops for fixed points B, N)
    for v, (x, y) in pos.items():
        w = neg[v]
        if w == v:
            ax.annotate("fix", (x + 0.18, y + 0.18), fontsize=9, color="blue")
    ax.set_title("Belnap four-valued lattice\\n(green = designated; B is a designated negation fixed point)")
    ax.axis("off")
    plt.tight_layout()
    plt.savefig("belnap_lattice.png", dpi=150)
    print("wrote belnap_lattice.png")

if __name__ == "__main__":
    plot_belnap()
